(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x));
function number(x,min,max,label){if(typeof x!=='number'||!Number.isFinite(x)||x<min||x>max)throw Error(label+' invalid');return x;}
function validateWave(w,types){if(!w||typeof w.id!=='string'||!w.id||typeof w.name!=='string'||!w.name.trim()||w.name.length>80)throw Error('Invalid wave name or ID');if(!Array.isArray(w.groups)||!w.groups.length||w.groups.length>32)throw Error('A wave must contain 1 to 32 groups');let total=0;const groups=w.groups.map(g=>{if(!g||!types[g.type])throw Error('Unknown enemy');number(g.count,1,100,'Quantity');if(!Number.isInteger(g.count))throw Error('Integer quantity required');total+=g.count;number(g.delay,0,600,'Delay');number(g.interval,0,60,'Interval');const stats={};for(const [key,min,max] of [['hp',1,10000],['damage',0,1000],['speed',0,15],['range',.1,20],['cooldown',.05,30]])if(g.stats?.[key]!==undefined)stats[key]=number(g.stats[key],min,max,key);return {type:g.type,count:g.count,delay:g.delay,interval:g.interval,stats};});if(total>500)throw Error('Maximum 500 monsters per wave');return {id:w.id,name:w.name.trim(),groups};}
function validateLibrary(data,types){if(!data||data.version!==1||!Array.isArray(data.waves)||data.waves.length>100||!Array.isArray(data.playlist)||data.playlist.length>100)throw Error('Invalid library format');const waves=data.waves.map(w=>{const valid=validateWave(w,types);for(const g of valid.groups)if(g.stats.range!==undefined)g.stats.range=root.RoundCircleSimulation.migrateRange(g.type,g.stats.range,data.combatVersion);return valid;});const ids=new Set(waves.map(w=>w.id));if(ids.size!==waves.length)throw Error('Duplicate wave IDs');const playlist=data.playlist.map(e=>{if(!ids.has(e.waveId)||!['clear','time'].includes(e.mode))throw Error('Invalid playlist entry');return {waveId:e.waveId,mode:e.mode,gap:number(e.gap,0,600,'Pause')};});const v=data.vortex||{rate:.96,startRadius:1.2,triggers:[]};
 if(!Array.isArray(v.triggers)||v.triggers.length>100)throw Error('Maximum 100 vortex thresholds');
 const vortex={rate:number(v.rate,0,10,'Growth'),startRadius:number(v.startRadius,.2,6,'Initial radius'),triggers:v.triggers.map(t=>{if(!ids.has(t.waveId))throw Error('Unknown threshold wave');return {waveId:t.waveId,radius:number(t.radius,.2,6,'Threshold')};})};
 return {version:1,combatVersion:2,waves,playlist,vortex};}
const VORTEX_MAX_RADIUS=6;
function vortexRemaining(radius,rate){const left=Math.max(0,VORTEX_MAX_RADIUS-radius);return left<=1e-9?0:rate>0?left*60/rate:Infinity;}
function formatRemaining(seconds){if(!Number.isFinite(seconds))return '∞';const total=Math.max(0,Math.ceil(seconds-1e-7));return Math.floor(total/60).toString().padStart(2,'0')+':'+(total%60).toString().padStart(2,'0');}
class WaveRunner{
 constructor(sim){this.sim=sim;this.stop();}
 stop(){this.records=[];this.serial=(this.serial||0)+1;this.nextWave=0;this.waveNumber=0;this.vortexPlan=null;this.resetId=this.sim.resetId;this.jobs=[];this.plan=null;this.active=null;this.index=0;this.state='Stopped';this.previous=this.sim.time;}
 track(w){const record={owner:'wave-'+this.serial+'-'+(++this.nextWave),waveId:w.id,number:this.nextWave,name:w.name,startedAt:this.sim.time,ids:[],done:false};this.records.push(record);this.sim.metrics.wavesStarted++;this.sim.events.push({type:'wave-launched',id:record.owner,name:w.name});return record.owner;}
 complete(){for(const r of this.records){if(!r.done&&!this.jobs.some(j=>j.owner===r.owner)&&r.ids.every(id=>!this.sim.get(id)||this.sim.get(id).hp<=0)){r.done=true;r.completedAt=this.sim.time;this.sim.metrics.wavesCompleted++;const event={type:'wave-complete',id:r.owner,name:r.name,number:r.number};this.sim.events.push(event);this.onWaveComplete?.(event);}}}
 schedule(w,owner){const now=this.sim.time;for(const g of w.groups)for(let i=0;i<g.count;i++)this.jobs.push({at:now+g.delay+i*g.interval,type:g.type,stats:clone(g.stats),owner});this.jobs.sort((a,b)=>a.at-b.at);}
 runWave(w){const valid=validateWave(w,root.RoundCircleSimulation.types);this.schedule(valid,this.track(valid));this.state='Manual wave : '+w.name;}
 start(data){const lib=validateLibrary(data,root.RoundCircleSimulation.types);if(!lib.playlist.length)throw Error('Add a wave to the playlist');this.stop();this.plan=clone(lib);this.launch();}
 startRun(data){const lib=validateLibrary(data,root.RoundCircleSimulation.types);if(lib.vortex.startRadius>=VORTEX_MAX_RADIUS)lib.vortex.startRadius=1.2;lib.vortex.rate=(VORTEX_MAX_RADIUS-lib.vortex.startRadius)/5;this.stop();this.sim.cfg.vortexRadius=lib.vortex.startRadius;this.sim.reset();this.startVortex(lib);return clone(lib.vortex);}
 startVortex(data){const lib=validateLibrary(data,root.RoundCircleSimulation.types);this.stop();this.sim.cfg.vortexRadius=lib.vortex.startRadius;this.vortexPlan={rate:lib.vortex.rate,triggers:lib.vortex.triggers.map(t=>({...t,wave:clone(lib.waves.find(w=>w.id===t.waveId)),state:t.radius<lib.vortex.startRadius?'skipped':'waiting'})).sort((a,b)=>a.radius-b.radius)};this.state='Vortex active';}
 setGrowthRate(rate){number(rate,0,10,'Growth');if(this.vortexPlan)this.vortexPlan.rate=rate;}
 grow(dt){const plan=this.vortexPlan;if(!plan)return;const target=Math.min(VORTEX_MAX_RADIUS,this.sim.cfg.vortexRadius+plan.rate*dt/60);const reached=new Set();for(const t of plan.triggers){if(t.state==='waiting'&&t.radius<=target+1e-9){t.state='fired';reached.add(t.radius);this.sim.cfg.vortexRadius=t.radius;this.schedule(t.wave,this.track(t.wave));}}for(const radius of reached)this.sim.events.push({type:'wave-start',number:++this.waveNumber,radius});this.sim.cfg.vortexRadius=target;this.state=target>=6?'Vortex: maximum radius reached':'Vortex active';}
 launch(){if(this.index>=this.plan.playlist.length){this.state='Playlist complete';this.plan=null;this.active=null;return;}const entry=this.plan.playlist[this.index],wave=this.plan.waves.find(w=>w.id===entry.waveId);this.active={owner:this.track(wave),ids:[],emittedAt:null,entry};this.state='Wave '+(this.index+1)+' / '+this.plan.playlist.length+' : '+wave.name;this.schedule(wave,this.active.owner);}
 tick(){if(this.sim.ended)return;const now=this.sim.time;if(this.resetId!==this.sim.resetId||now<this.previous){this.stop();return;}this.complete();if(this.isBlocked?.()){this.previous=now;return;}this.grow(Math.max(0,now-this.previous));this.previous=now;for(let i=0;i<this.jobs.length;){const j=this.jobs[i];if(j.at>now)break;const m=this.sim.spawn(j.type,j.stats);if(!m)break;const record=this.records.find(r=>r.owner===j.owner);if(record)record.ids.push(m.id);if(this.active&&j.owner===this.active.owner)this.active.ids.push(m.id);this.jobs.splice(i,1);}this.complete();if(this.isBlocked?.())return;if(this.active){const a=this.active;if(!this.jobs.some(j=>j.owner===a.owner)){if(a.emittedAt===null)a.emittedAt=now;const clear=a.ids.every(id=>!this.sim.get(id)||this.sim.get(id).hp<=0);if((a.entry.mode==='time'||clear)&&now-a.emittedAt>=a.entry.gap){this.index++;this.launch();}}}else if(!this.jobs.length&&!this.plan&&this.state.startsWith('Manual wave'))this.state='Wave deployed';}
}
const seed={version:1,combatVersion:2,vortex:{rate:.96,startRadius:1.2,triggers:[]},waves:[{id:'discovery',name:'01 · First Visitors',groups:[{type:'maw',count:4,delay:0,interval:1.5,stats:{}}]},{id:'pressure',name:'02 · Pressure on the Houses',groups:[{type:'spitter',count:3,delay:0,interval:2,stats:{}},{type:'carapace',count:2,delay:3,interval:4,stats:{}},{type:'runner',count:6,delay:4,interval:.5,stats:{}}]},{id:'elites',name:'03 · The Owners',groups:[{type:'cathedral',count:1,delay:0,interval:0,stats:{}},{type:'widow',count:1,delay:6,interval:0,stats:{}},{type:'maw',count:5,delay:8,interval:1,stats:{}}]}],playlist:[{waveId:'discovery',mode:'clear',gap:3},{waveId:'pressure',mode:'clear',gap:4},{waveId:'elites',mode:'clear',gap:3}]};
root.RoundCircleWaves={WaveRunner,validateWave,validateLibrary,seed,vortexRemaining,formatRemaining};if(typeof module!=='undefined')module.exports=root.RoundCircleWaves;
})(typeof window!=='undefined'?window:globalThis);
